long long fib(long long n) {
    const long long M = 1e9 + 7; using Mat = array<array<long long,2>,2>;
    auto mul = [&](const Mat& a, const Mat& b) { Mat c{}; for (int i = 0; i < 2; i++) for (int j = 0; j < 2; j++) c[i][j] = (a[i][0] * b[0][j] + a[i][1] * b[1][j]) % M; return c; };
    Mat r{{{1, 0}, {0, 1}}}, x{{{1, 1}, {1, 0}}}; while (n) { if (n & 1) r = mul(r, x); x = mul(x, x); n >>= 1; } return r[0][1];
}
